using System.Collections.ObjectModel;
using System.Data;
using System.Windows;
using ClosedXML.Excel;
using ExcelPlanner.Commands;
using ExcelPlanner.Models;
using ExcelPlanner.Services;
using Microsoft.Win32;

namespace ExcelPlanner.ViewModels
{
    public class MainViewModel : ObservableObject
    {
        private readonly ExcelService _excelService;
        private XLWorkbook? _workbook;
        private DataTable? _currentTable;

        private string _statusText = "Sẵn sàng";
        public string StatusText
        {
            get => _statusText;
            set => SetProperty(ref _statusText, value);
        }

        private List<string> _sheetNames = new();
        public List<string> SheetNames
        {
            get => _sheetNames;
            set => SetProperty(ref _sheetNames, value);
        }

        private string? _selectedSheetName;
        public string? SelectedSheetName
        {
            get => _selectedSheetName;
            set
            {
                if (SetProperty(ref _selectedSheetName, value))
                {
                    LoadSheetData(value);
                }
            }
        }

        private DataView? _dataView;
        public DataView? DataView
        {
            get => _dataView;
            set => SetProperty(ref _dataView, value);
        }

        private string _rowIndexInfo = "";
        public string RowIndexInfo
        {
            get => _rowIndexInfo;
            set => SetProperty(ref _rowIndexInfo, value);
        }

        private string _rowSummary = "";
        public string RowSummary
        {
            get => _rowSummary;
            set => SetProperty(ref _rowSummary, value);
        }

        private string _chartSuggestion = "";
        public string ChartSuggestion
        {
            get => _chartSuggestion;
            set => SetProperty(ref _chartSuggestion, value);
        }

        public ObservableCollection<TaskItem> Tasks { get; } = new();

        public RelayCommand OpenFileCommand { get; }
        public RelayCommand AddTaskCommand { get; }
        public RelayCommand<object?> SelectionChangedCommand { get; }

        public MainViewModel()
        {
            _excelService = new ExcelService();
            OpenFileCommand = new RelayCommand(_ => OpenFile());
            AddTaskCommand = new RelayCommand(_ => AddTask(), _ => DataView != null && SelectedRow != null);
            SelectionChangedCommand = new RelayCommand<object?>(param => UpdateSelectionInfo(param));
        }

        private DataRowView? _selectedRow;
        public DataRowView? SelectedRow
        {
            get => _selectedRow;
            set
            {
                if (SetProperty(ref _selectedRow, value))
                {
                    AddTaskCommand.RaiseCanExecuteChanged();
                }
            }
        }

        private void OpenFile()
        {
            var dialog = new OpenFileDialog
            {
                Filter = "Excel Files|*.xlsx;*.xls",
                Title = "Chọn file Excel để xem và lập kế hoạch"
            };

            if (dialog.ShowDialog() == true)
            {
                try
                {
                    _workbook = _excelService.LoadWorkbook(dialog.FileName);
                    SheetNames = _excelService.GetSheetNames(_workbook);
                    if (SheetNames.Count > 0)
                    {
                        SelectedSheetName = SheetNames[0];
                    }
                    StatusText = $"Đã mở: {System.IO.Path.GetFileName(dialog.FileName)}";
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Lỗi đọc file: {ex.Message}", "Lỗi", MessageBoxButton.OK, MessageBoxImage.Error);
                }
            }
        }

        private void LoadSheetData(string? sheetName)
        {
            if (_workbook == null || string.IsNullOrEmpty(sheetName)) return;

            try
            {
                _currentTable = _excelService.GetSheetData(_workbook, sheetName);
                DataView = _currentTable?.DefaultView;
                StatusText = _currentTable == null 
                    ? $"Sheet: {sheetName} (Trống)" 
                    : $"Sheet: {sheetName} ({_currentTable.Rows.Count} dòng)";
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Không thể đọc sheet '{sheetName}': {ex.Message}", "Lỗi dữ liệu", MessageBoxButton.OK, MessageBoxImage.Warning);
                StatusText = "Lỗi đọc sheet";
            }
        }

        private void UpdateSelectionInfo(object? parameter)
        {
            if (parameter is DataRowView rowView)
            {
                SelectedRow = rowView;
                var row = rowView.Row;
                RowIndexInfo = $"Dòng thứ: {row.Table.Rows.IndexOf(row) + 2}";

                var values = row.ItemArray.Where(v => v != DBNull.Value && !string.IsNullOrEmpty(v.ToString())).Take(5);
                RowSummary = string.Join(", ", values);

                SuggestChart(row);
            }
        }

        private void SuggestChart(DataRow row)
        {
            int numericCount = 0;
            foreach (var item in row.ItemArray)
            {
                if (item is double or int or decimal) numericCount++;
            }

            ChartSuggestion = numericCount switch
            {
                0 => "Dòng này chủ yếu là văn bản. Phù hợp để làm nhãn hoặc mô tả.",
                1 => "Có 1 giá trị số. Phù hợp với biểu đồ Pie (tròn) để so sánh tỷ trọng.",
                _ => "Có nhiều giá trị số. Phù hợp với biểu đồ Column (cột) hoặc Line (đường) để xem xu hướng."
            };
        }

        private void AddTask()
        {
            if (SelectedRow == null) return;

            var row = SelectedRow.Row;
            var desc = $"Task từ dòng {row.Table.Rows.IndexOf(row) + 2}: {RowSummary}";
            Tasks.Add(new TaskItem { Description = desc, IsDone = false });
        }
    }
}

